import json

log_path = "/Users/dasean/.gemini/antigravity/brain/339f5518-9980-4e89-a848-d3d6b7f639c9/.system_generated/logs/transcript_full.jsonl"

print("🔍 Scanning for write_to_file index.js in previous transcript...")
with open(log_path, 'r', encoding='utf-8') as f:
    for line in f:
        try:
            step = json.loads(line)
            tool_calls = step.get('tool_calls', [])
            for call in tool_calls:
                name = call.get('name')
                args = call.get('args', {})
                if name == 'write_to_file' and 'index.js' in str(args.get('TargetFile')):
                    print(f"👉 Step {step.get('step_index')}: write_to_file Target={args.get('TargetFile')}")
        except Exception as e:
            pass
